insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sg', '/flags/history/sg-1946.svg', '1946-04-01', '1952-01-01', 'Colonie de Singapour (1946-1952)', 'Colony of Singapore (1946–1952)', 'Séparée des Établissements des détroits en 1946, Singapour devient une colonie de la Couronne avec son propre Blue Ensign.', 'Split from the Straits Settlements in 1946, Singapore became a Crown colony with its own Blue Ensign.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('sg', '/flags/history/sg-1925.svg', '1925-01-01', '1946-04-01', 'Établissements des détroits (1925-1946)', 'Straits Settlements (1925–1946)', 'Pavillon de la colonie regroupant Singapour, Malacca et Penang, dont le badge porte trois couronnes.', 'Flag of the colony grouping Singapore, Malacca and Penang, whose badge bears three crowns.');
